DECLARE @e UNIQUEIDENTIFIER, @v UNIQUEIDENTIFIER, @no INT, @payload NVARCHAR(MAX) = N'{"g":1,"kind":"relayWord","key":"RELAY_WORD_SEL_221F","name":"SEL-221F Relay Word","settingsTemplate":"SETTINGS_TEXT_SEL_221F","source":"SEL-221F-2/-3/-4, SEL-121F-2/-3 Instruction Manual, date code 981207 (Z:\\Archive-WorkingData-Cloud\\Work\\DATA\\Manuals\\SEL\\221F-2-3-4_IM_19981207.pdf)","bitOrder":"The left bit of a row is the most significant bit of its byte: A4 -> 1010 0100 laid over 67N 51NP 51NT 50NG 50P 50H IN1 REJO (3-15). One selects and zero deselects a member of the mask (3-20).","rows":[[{"code":"Z1P","meaning":"Zone 1 phase fault, instantaneous output (set by Z1%)","cite":"2-21 (Table 2.4); 2-5 (Table 2.1)"},{"code":"Z1G","meaning":"Zone 1 ground fault, instantaneous output (set by Z1%)","cite":"2-21 (Table 2.4); 2-5 (Table 2.1)"},{"code":"Z2PT","meaning":"Zone 2 phase fault, time delayed (set by Z2% and Z2DP)","cite":"2-21 (Table 2.4); 2-5 (Table 2.1)"},{"code":"Z2GT","meaning":"Zone 2 ground fault, time delayed (set by Z2% and Z2DG)","cite":"2-21 (Table 2.4); 2-5 (Table 2.1)"},{"code":"Z3","meaning":"Zone 3 phase or ground fault, instantaneous output (set by Z3%)","cite":"2-21 (Table 2.4); 2-5 (Table 2.1)"},{"code":"Z3T","meaning":"Zone 3 phase or ground fault, time delayed (set by Z3% and Z3D)","cite":"2-21 (Table 2.4); 2-5 (Table 2.1)"},{"code":"3P21","meaning":"Three-phase fault condition detected by phase distance relays","cite":"2-21 (Table 2.4); 2-5 (Table 2.1)"},{"code":"32Q","meaning":"Negative-sequence directional element","cite":"2-21 (Table 2.4); 2-5 (Table 2.1)"}],[{"code":"67N","meaning":"Residual instantaneous overcurrent (set by 67NP and 67NTC)","cite":"2-21 (Table 2.4); 2-5 (Table 2.1)"},{"code":"51NP","meaning":"Pickup of residual time-O/C (set by 51NP and 51NTC)","cite":"2-21 (Table 2.4); 2-5 (Table 2.1)"},{"code":"51NT","meaning":"Timeout of residual time-overcurrent element","cite":"2-21 (Table 2.4); 2-5 (Table 2.1)"},{"code":"50NG","meaning":"Sensitive residual or phase overcurrent condition (set by 50NG)","cite":"2-21 (Table 2.4); 2-5 (Table 2.1)"},{"code":"50P","meaning":"Phase overcurrent condition (set by 50P)","cite":"2-21 (Table 2.4); 2-5 (Table 2.1)"},{"code":"50H","meaning":"High-set phase overcurrent condition (set by 50H)","cite":"2-21 (Table 2.4); 2-5 (Table 2.1)"},{"code":"IN1","meaning":"Logic Input 1 (use for direct trip, reclose initiate/cancel, etc.)","cite":"2-21 (Table 2.4); 2-5 (Table 2.1)"},{"code":"REJO","meaning":"Remote-end-just-opened condition","cite":"2-21 (Table 2.4); 2-5 (Table 2.1)"}],[{"code":"LOP","meaning":"Loss-of-potential condition","cite":"2-21 (Table 2.4); 2-5 (Table 2.1)"},{"code":"TRIP","meaning":"Follows trip condition","cite":"2-21 (Table 2.4); 2-5 (Table 2.1)"},{"code":"27S","meaning":"Synchronizing undervoltage condition (Tests VS against VLO setting)","cite":"2-21 (Table 2.4); 2-5 (Table 2.1)"},{"code":"27P","meaning":"Polarizing undervoltage condition (Tests VP1 against VLO setting)","cite":"2-21 (Table 2.4); 2-5 (Table 2.1)"},{"code":"59S","meaning":"Synchronizing overvoltage condition (Tests VS against VHI setting)","cite":"2-21 (Table 2.4); 2-5 (Table 2.1)"},{"code":"59P","meaning":"Polarizing overvoltage condition (Tests VP1 against VHI setting)","cite":"2-21 (Table 2.4); 2-5 (Table 2.1)"},{"code":"SSC","meaning":"Synchronization-supervised condition (set by 25DV, 25T, SYNCP)","cite":"2-21 (Table 2.4); 2-5 (Table 2.1)"},{"code":"VSC","meaning":"Voltage-supervised condition (set by PSVC for disable/LSDP/LPDS/either)","cite":"2-21 (Table 2.4); 2-5 (Table 2.1)"}]],"footnote":"VP1 = positive-sequence voltage applied to the polarizing voltage inputs (2-21).","variants":[{"models":"SEL-221F-3/121F-3, SEL-221F-4","row":3,"bit":2,"code":"BFT","note":"The TRIP bit is replaced by the BFT bit in the SEL-221F-3/121F-3 and SEL-221F-4 models.","cite":"5-33 (Note 2); 2-51"}],"testing":{"bits":["3P21","32Q","51NP","50NG","50P","27S","27P","59S","59P"],"note":"The following bits are included to assist in relay testing: 3P21, 32Q, 51NP, 50NG, 50P, 27S, 27P, 59S, 59P. This does not exclude the use of these bits in one of four trip or programmable output contacts if required by your application.","cite":"5-38"},"masks":{"MTU":{"name":"Mask for trip unconditional","purpose":"Elements selected in this mask do not require that external conditions be met to initiate a trip. If an element masked in the MTU logic mask picks up, the TRIP output contacts close. You must be certain that elements used in this mask coordinate with other system protective devices.","caution":"Unless your application permits, it is not advisable to set non-directional overcurrent elements in the MTU logic mask.","typical":["Z1P","Z1G","67N","51NT","Z2PT","Z2GT","Z3T","IN1"],"never":["TRIP"],"neverNote":"Never mask the TRIP bit into the MTU logic mask. This causes an undesirable seal-in of TRIP output contacts.","example":"F4 A2 00","cite":"5-33"},"MPT":{"name":"Mask for trip with permissive-trip asserted","purpose":"The relay closes the TRIP output when the Permissive Trip (PT) input is asserted or the REJO condition is enabled and asserted and elements selected in the MPT mask pick up.","caution":"As with the MTU logic mask, it is not advisable to mask non-directional elements in the MPT logic mask unless your application permits.","typical":["Z3"],"never":["TRIP"],"neverNote":"Never mask the TRIP bit into the MPT logic mask. This causes an undesirable seal-in of TRIP output contacts.","example":"08 00 00","cite":"5-33, 5-34"},"MTB":{"name":"Mask for trip with block-trip unasserted","purpose":"The relay closes the TRIP output when the Block Trip (BT) input is not asserted and elements selected in this mask pick up. BT input assertion serves as an external qualifying condition.","caution":"As with the MTU logic mask, it is not advisable to mask nondirectional elements in the MTB logic mask unless your application permits.","typical":[],"never":["TRIP"],"neverNote":"Never mask the TRIP bit into the MTB logic mask. This causes an undesirable seal-in of TRIP output contacts.","example":"00 00 00","cite":"5-34"},"MTO":{"name":"Mask for trip with breaker open","purpose":"The relay closes the TRIP output when the 52BT element is asserted and elements selected in this mask pick up. The 52BT element is a time delayed, inverted follower of the 52A input. This tripping mask differs from the MTU, MPT, and MTB tripping masks because it is acceptable to mask sensitive nondirectional elements into MTO in certain applications.","caution":"Such masking is advisable except in applications where the line breaker is closed into a line energized from the remote terminal (i.e. synchronized closures).","typical":["Z1P","Z1G","67N","50H","Z3"],"never":["TRIP"],"neverNote":"Never mask the TRIP bit into the MTO logic mask. This causes an undesirable seal-in of TRIP output contacts.","example":"FC A4 00","cite":"5-35"},"MA1":{"name":"Mask for A1 relay control","purpose":"Any element listed in the Relay Word may be masked into these programmable output contacts. Guidelines to follow when masking elements into each mask depends on equipment connected to the contact outputs. If external equipment is not connected to the contact outputs, you may set elements in these masks to enhance event report analysis.","caution":"","typical":["SSC"],"never":[],"neverNote":"","example":"00 00 02","cite":"5-35, 5-36"},"MA2":{"name":"Mask for A2 relay control","purpose":"Any element listed in the Relay Word may be masked into these programmable output contacts. The A2 output contact asserts when the VSC bit asserts, indicating that voltage conditions have fulfilled the voltage checking requirements.","caution":"","typical":["VSC"],"never":[],"neverNote":"","example":"00 00 01","cite":"5-35, 5-36"},"MA3":{"name":"Mask for A3 relay control","purpose":"Any element listed in the Relay Word may be masked into these programmable output contacts. In the manual''s example the A3 output contact asserts when any reclose initiate condition set in the MRI logic mask is fulfilled.","caution":"","typical":["Z1P","Z1G","Z2PT","Z2GT","67N"],"never":[],"neverNote":"","example":"F0 80 00","cite":"5-35, 5-36"},"MA4":{"name":"Mask for A4 relay control","purpose":"Any element listed in the Relay Word may be masked into these programmable output contacts. In the manual''s example the A4 output contact asserts when any reclose cancel condition set in the MRC logic mask is fulfilled.","caution":"","typical":["Z3T","51NT"],"never":[],"neverNote":"","example":"04 20 00","cite":"5-35, 5-37"},"MRI":{"name":"Mask for reclose initiate","purpose":"If an element masked in the MRI mask is asserted when the TRIP output contacts close, reclosing is initiated unless a reclose cancel condition occurs. Reclose initiation is subordinate to reclose cancel.","caution":"","typical":["67N","Z1P","Z1G","Z2PT","Z2GT"],"never":[],"neverNote":"","example":"F0 80 00","cite":"5-37"},"MRC":{"name":"Mask for reclose cancel","purpose":"If an element masked in the MRC mask is asserted when the TRIP output contacts close, reclosing is cancelled even if a reclose initiate condition occurs. Reclose initiation is subordinate to reclose cancellation.","caution":"","typical":["Z3T","51NT"],"never":[],"neverNote":"","example":"04 20 00","cite":"5-37, 5-38"}}}';
